(32401, 0, 65, 32519, 1466.761, 417.194, -83.963, 3.5075, 6, 30000, '32401 - Battle for the Undercity - apothecarium wave - Failed Experiment'),
(32401, 0, 65, 32519, 1466.157, 427.219, -83.963, 3.5075, 6, 30000, '32401 - Battle for the Undercity - apothecarium wave - Failed Experiment'),
(32401, 0, 65, 32519, 1459.622, 419.154, -83.963, 3.5075, 6, 30000, '32401 - Battle for the Undercity - apothecarium wave - Failed Experiment'),
(32401, 0, 65, 32519, 1470.208, 420.739, -83.963, 3.5075, 6, 30000, '32401 - Battle for the Undercity - apothecarium wave - Failed Experiment'),
(32401, 0, 65, 32519, 1461.072, 426.89, -83.963, 3.5075, 6, 30000, '32401 - Battle for the Undercity - apothecarium wave - Failed Experiment'),
(32401, 0, 65, 32519, 1463.727, 415.893, -83.963, 3.5075, 6, 30000, '32401 - Battle for the Undercity - apothecarium wave - Failed Experiment'),
(32401, 0, 65, 32519, 1469.334, 426.05, -83.963, 3.5075, 6, 30000, '32401 - Battle for the Undercity - apothecarium wave - Failed Experiment'),
(32401, 0, 65, 32519, 1458.075, 422.257, -83.963, 3.5075, 6, 30000, '32401 - Battle for the Undercity - apothecarium wave - Failed Experiment'),
(32401, 0, 66, 32483, 1675.763, 562.293, -18.377, 1.501, 8, 0, '32401 - Battle for the Undercity - Engorged Blight Worm');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(31418, 5, 0, 'VARIAN, NO! STOP!', 14, 0, 100, 1, 0, 16122, 32709, 0, 'Lady Jaina Proudmoore - Battle for the Undercity'),
(31418, 6, 0, 'It did not have to be like this...', 12, 0, 100, 1, 0, 16123, 32711, 0, 'Lady Jaina Proudmoore - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(31530, 0, 0, 'Do not let them pass, minions!', 14, 0, 100, 0, 0, 16289, 32943, 0, 'Grand Apothecary Putress - Battle for the Undercity'),
(31530, 1, 0, 'KILL THEM! My work must not be interrupted!', 14, 0, 100, 0, 0, 16290, 32944, 0, 'Grand Apothecary Putress - Battle for the Undercity'),
(31530, 2, 0, 'Stare into the abyss and watch as it blackens your souls!', 14, 0, 100, 0, 0, 16294, 32949, 0, 'Grand Apothecary Putress - Battle for the Undercity'),
(31530, 3, 0, 'You are no match for my creations!', 14, 0, 100, 0, 0, 16295, 32952, 0, 'Grand Apothecary Putress - Battle for the Undercity'),
(31530, 4, 0, 'This cannot be happening!', 14, 0, 100, 0, 0, 16296, 32953, 0, 'Grand Apothecary Putress - Battle for the Undercity'),
(31530, 5, 0, 'It will not end like this! I''ve worked too hard! So many years... I... I will consume more energy!', 14, 0, 100, 0, 0, 16291, 32948, 0, 'Grand Apothecary Putress - Battle for the Undercity'),
(31530, 6, 0, 'The power washes through me! I see... EVERYTHING!', 14, 0, 100, 0, 0, 16292, 32950, 0, 'Grand Apothecary Putress - Battle for the Undercity'),
(31530, 7, 0, 'MORE SUFFERING AWAITS!', 14, 0, 100, 0, 0, 16293, 32951, 0, 'Grand Apothecary Putress - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(31565, 0, 0, 'Welcome to my kingdom of darkness!', 14, 0, 100, 1, 0, 16156, 32375, 0, 'Varimathras - Battle for the Undercity'),
(31565, 1, 0, 'Did you enjoy my minion''s terrible creation? Potent, is it not?', 14, 0, 100, 1, 0, 16157, 32376, 0, 'Varimathras - Battle for the Undercity'),
(31565, 2, 0, 'But enough prattling! You wish to reclaim your city? Come then, heroes! Your souls will fuel the host! You will have this place back in pieces!', 14, 0, 100, 1, 0, 16158, 32383, 0, 'Varimathras - Battle for the Undercity'),
(31565, 3, 0, 'Clever girl...', 14, 0, 100, 1, 0, 16159, 32521, 0, 'Varimathras - Battle for the Undercity'),
(31565, 4, 0, 'My brothers have grown hungry. Your souls will sate their appetites.', 14, 0, 100, 1, 0, 16160, 32524, 0, 'Varimathras - Battle for the Undercity'),
(31565, 5, 0, 'Bring down the halls! NOW!', 14, 0, 100, 1, 0, 16161, 32568, 0, 'Varimathras - Battle for the Undercity'),
(31565, 6, 0, 'Welcome to your future -- what little there is left of it...', 14, 0, 100, 1, 0, 16163, 32580, 0, 'Varimathras - Battle for the Undercity'),
(31565, 7, 0, 'Too long... Tireless, endless planning... It will not end like this...', 14, 0, 100, 1, 0, 16164, 32610, 0, 'Varimathras - Battle for the Undercity'),
(31565, 8, 0, 'Need more time... The Master is near...', 14, 0, 100, 1, 0, 16165, 32611, 0, 'Varimathras - Battle for the Undercity'),
(31565, 9, 0, 'Such power! Can you not feel it, mortals? Cease this foolishness and join me!', 14, 0, 100, 1, 0, 16166, 32612, 0, 'Varimathras - Battle for the Undercity'),
(31565, 10, 0, 'I will not fail! Not again!', 14, 0, 100, 1, 0, 16167, 32613, 0, 'Varimathras - Battle for the Undercity'),
(31565, 11, 0, 'I cannot hold... Destabilizing...', 14, 0, 100, 1, 0, 16168, 32614, 0, 'Varimathras - Battle for the Undercity'),
(31565, 12, 0, 'A thousand-thousand pardons, Master! I will deal with these intruders myself!', 14, 0, 100, 1, 0, 16162, 32579, 0, 'Varimathras - Battle for the Undercity'),
(31565, 13, 0, 'Years... wasted...', 14, 0, 100, 1, 0, 16169, 32617, 0, 'Varimathras - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(31650, 0, 0, 'HEROES OF THE HORDE, YOUR WARCHIEF CALLS!', 14, 0, 100, 1, 0, 16187, 32339, 0, 'Thrall - Battle for the Undercity'),
(31650, 1, 0, 'Gather behind me at the gates of the Undercity! Soon we march upon our fallen city and reclaim it - FOR THE HORDE!', 14, 0, 100, 1, 0, 16188, 32361, 0, 'Thrall - Battle for the Undercity'),
(31650, 2, 0, 'Blood and thunder, champions of the Horde! We fight on this day for our fallen brothers and sisters! Mourn them not for they all died with honor in their hearts!', 14, 0, 100, 1, 0, 16189, 32340, 0, 'Thrall - Battle for the Undercity'),
(31650, 3, 0, 'Though we face great conflict, our might combined shall obliterate those who would oppose us! The grave injustices committed against the Horde will be met by an unstoppable force of reckoning!', 14, 0, 100, 1, 0, 16190, 32341, 0, 'Thrall - Battle for the Undercity'),
(31650, 4, 0, 'I call to you great spirits! Grant the Horde your blessing! For on this day our cause is righteous and just!', 14, 0, 100, 1, 0, 16191, 32342, 0, 'Thrall - Battle for the Undercity'),
(31650, 5, 0, 'Spirits of wind, carry to Saurfang the Younger the song of war! May ALL of our fallen brethren be vindicated by this battle!', 14, 0, 100, 1, 0, 16192, 32362, 0, 'Thrall - Battle for the Undercity'),
(31650, 6, 0, 'The battle for the Undercity begins now! Sound the horns of war! Champions of the Horde, be empowered by the might of your Warchief!', 14, 0, 100, 1, 0, 16193, 32363, 0, 'Thrall - Battle for the Undercity'),
(31650, 7, 0, 'ONWARD!', 14, 0, 100, 1, 0, 16195, 32366, 0, 'Thrall - Battle for the Undercity'),
(31650, 8, 0, 'Great wind brother, clear our path!', 14, 0, 100, 1, 0, 16196, 32367, 0, 'Thrall - Battle for the Undercity'),
(31650, 9, 0, 'You must answer to the elements, demon!', 14, 0, 100, 1, 0, 16197, 32368, 0, 'Thrall - Battle for the Undercity'),
(31650, 10, 0, 'Great water spirit, wash away this corruption!', 12, 0, 100, 1, 0, 16194, 32369, 0, 'Thrall - Battle for the Undercity'),
(31650, 11, 0, 'ATTACK!!!!', 14, 0, 100, 1, 0, 16198, 32396, 0, 'Thrall - Battle for the Undercity'),
(31650, 12, 0, 'The courtyard is ours! Onward to the inner sanctum!', 12, 0, 100, 1, 0, 16199, 32460, 0, 'Thrall - Battle for the Undercity'),
(31650, 13, 0, 'HOLD! They''ve destroyed the elevator!', 12, 0, 100, 1, 0, 16200, 32461, 0, 'Thrall - Battle for the Undercity'),
(31650, 14, 0, 'Great air spirit, hear my call once more!', 12, 0, 100, 1, 0, 16201, 32490, 0, 'Thrall - Battle for the Undercity'),
(31650, 15, 0, 'The spirits of air have heard my call. Cyclones will lower us to safety. Now we jump!', 12, 0, 100, 1, 0, 16202, 32491, 0, 'Thrall - Battle for the Undercity'),
(31650, 16, 0, 'We have breached the inner sanctum, heroes! We press on!', 14, 0, 100, 1, 0, 16203, 32494, 0, 'Thrall - Battle for the Undercity'),
(31650, 17, 0, 'Lead the way, Dark Lady. We will follow.', 12, 0, 100, 1, 0, 16204, 32496, 0, 'Thrall - Battle for the Undercity'),
(31650, 18, 0, 'Is that all, demon? Have you nothing left to throw at us?', 14, 0, 100, 1, 0, 16205, 32553, 0, 'Thrall - Battle for the Undercity'),
(31650, 19, 0, 'We come for you! Prepare yourself!', 14, 0, 100, 1, 0, 16206, 32564, 0, 'Thrall - Battle for the Undercity'),
(31650, 20, 0, 'COWARD! You think to stop the Warchief of the Horde with pebbles? I will show you the true power of the elements!', 14, 0, 100, 1, 0, 16207, 32565, 0, 'Thrall - Battle for the Undercity'),
(31650, 21, 0, 'Great spirits of the earth, help us in our hour of need!', 14, 0, 100, 1, 0, 16208, 32575, 0, 'Thrall - Battle for the Undercity'),
(31650, 22, 0, 'LET''S GO! QUICKLY!', 14, 0, 100, 1, 0, 16210, 32583, 0, 'Thrall - Battle for the Undercity'),
(31650, 23, 0, 'What is this?', 14, 0, 100, 0, 0, 0, 32584, 0, 'Thrall - Battle for the Undercity'),
(31650, 24, 0, 'WE ARE VICTORIOUS!', 14, 1, 100, 1, 0, 16212, 32643, 0, 'Thrall - Battle for the Undercity'),
(31650, 25, 0, 'The Undercity belongs to the Horde once more! LOK''TAR!', 14, 1, 100, 1, 0, 16214, 32644, 0, 'Thrall - Battle for the Undercity'),
(31650, 26, 0, 'Dark Lady, join me! You have fought hard and spilled much blood for this right. The Royal Quarter belongs to you!', 12, 0, 100, 1, 0, 16215, 32646, 0, 'Thrall - Battle for the Undercity'),
(31650, 27, 0, 'We shall, Sylvanas...', 12, 0, 100, 1, 0, 16216, 32648, 0, 'Thrall - Battle for the Undercity'),
(31650, 28, 0, 'Alliance horns? Stay on guard!', 12, 0, 100, 1, 0, 16217, 32649, 0, 'Thrall - Battle for the Undercity'),
(31650, 29, 0, 'It ends like it began...', 12, 0, 100, 1, 0, 16218, 32728, 0, 'Thrall - Battle for the Undercity'),
(31650, 30, 0, 'All that we have fought for in this world is lost. The hopes and dreams carried by my father and mother... by Doomhammer... Gone...', 12, 0, 100, 1, 0, 16219, 32729, 0, 'Thrall - Battle for the Undercity'),
(31650, 31, 0, 'If only you were here right now, old friend. You would know what to do.', 12, 0, 100, 1, 0, 16220, 32730, 0, 'Thrall - Battle for the Undercity'),
(31650, 32, 0, '%s nods.', 16, 0, 100, 0, 0, 0, 32734, 0, 'Thrall - Battle for the Undercity'),
(31650, 33, 0, 'It''s good to have you back, Varok, old friend. I''m sorry about your boy.', 12, 0, 100, 1, 0, 16221, 32735, 0, 'Thrall - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(31651, 0, 0, '%s begins to sing.', 41, 0, 100, 0, 0, 0, 32427, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(31651, 1, 0, 'The shaft is trapped, Warchief. A fall would mean certain death.', 12, 0, 100, 1, 0, 16300, 32462, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(31651, 2, 0, 'What have they done to my beautiful city!', 12, 0, 100, 1, 0, 16301, 32489, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(31651, 3, 0, 'The only redemption for the traitors responsible for this will be an agonizing death. My vengeance will be swift and without mercy.', 12, 0, 100, 1, 0, 16302, 32495, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(31651, 4, 0, 'Very well, Warchief. The Royal Quarter is this way. Stay on guard. There is no telling what Varimathras and Putress have in store for us.', 12, 0, 100, 1, 0, 16303, 32497, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(31651, 5, 0, 'You disgust me.', 12, 0, 100, 0, 0, 0, 32502, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(31651, 5, 1, 'Beg for your miserable life!', 12, 0, 100, 0, 0, 0, 32504, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(31651, 5, 2, 'The Banshee Queen has plans for you!', 12, 0, 100, 0, 0, 0, 32503, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(31651, 5, 3, 'The Horde will be victorious!', 12, 0, 100, 0, 0, 0, 32500, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(31651, 5, 4, 'ON YOUR KNEES!', 12, 0, 100, 0, 0, 0, 32505, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(31651, 5, 5, 'You will be reunited with your master soon - in the afterlife.', 12, 0, 100, 0, 0, 0, 32501, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(31651, 6, 0, 'HOLD! I sense dark magic. Demon magic... Stand ready!', 12, 0, 100, 1, 0, 16304, 32520, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(31651, 7, 0, 'The Royal Quarter is just up ahead, Warchief.', 12, 0, 100, 1, 0, 16305, 32567, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity'),
(31651, 8, 0, 'Such will be the fate of all enemies of the Horde, Warchief.  Now we must deal with the wretch, Putress.', 12, 0, 100, 1, 0, 16306, 32647, 0, 'Lady Sylvanas Windrunner - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(31654, 0, 0, 'We''re taking it back!', 14, 1, 100, 0, 0, 0, 32329, 0, 'Horde Demolitionist - Battle for the Undercity'),
(31654, 0, 1, 'This one''s for Saurfang!', 14, 1, 100, 0, 0, 0, 32327, 0, 'Horde Demolitionist - Battle for the Undercity'),
(31654, 0, 2, 'FIRE IN THE HOLE!', 14, 1, 100, 0, 0, 0, 32326, 0, 'Horde Demolitionist - Battle for the Undercity'),
(31654, 0, 3, 'We''ll burn it to the ground before giving it to you!', 14, 1, 100, 0, 0, 0, 32330, 0, 'Horde Demolitionist - Battle for the Undercity'),
(31654, 0, 4, 'BURN IN HELLFIRE!', 14, 1, 100, 0, 0, 0, 32328, 0, 'Horde Demolitionist - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(31739, 0, 0, 'How could we not have seen this coming, to think a Dreadlord could be trusted!', 12, 0, 100, 0, 0, 0, 32267, 0, 'Warsong Battleguard - Battle for the Undercity'),
(31739, 0, 1, 'Forward to glory, Orcs!', 12, 0, 100, 0, 0, 0, 32265, 0, 'Warsong Battleguard - Battle for the Undercity'),
(31739, 0, 2, 'Prepare for battle, it looks like the Apothecarium already has their Blight aimed at the entrance!', 12, 0, 100, 0, 0, 0, 32264, 0, 'Warsong Battleguard - Battle for the Undercity'),
(31739, 1, 0, 'For the Horde!', 14, 0, 100, 0, 0, 0, 32561, 0, 'Warsong Battleguard - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(31844, 0, 0, 'Varimathras has released the Blight aberration!', 41, 0, 100, 0, 0, 0, 32476, 0, 'Blight Aberration - Battle for the Undercity'),
(31844, 1, 0, 'YAAAAAAAARGGGGHHHHH!!!!', 14, 0, 100, 0, 0, 0, 32437, 0, 'Blight Aberration - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(32160, 0, 0, 'The air around you crackles as Khanok the Impassable appears!', 41, 0, 100, 0, 0, 0, 32544, 0, 'Khanok the Impassable - Battle for the Undercity'),
(32160, 1, 0, 'No hope for you!', 14, 0, 100, 0, 0, 0, 32545, 0, 'Khanok the Impassable - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(32277, 0, 0, 'YOU HAVE FAILED ME, VARIMATHRAS!', 14, 0, 100, 0, 0, 16180, 32618, 0, 'A distant voice - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(32303, 0, 0, 'I was away for too long. My absence cost us the lives of some of our greatest heroes. Trash like you and this evil witch were allowed to roam free -- unchecked.', 12, 0, 100, 1, 0, 16073, 32691, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32303, 1, 0, 'The time has come to make things right. To disband your treacherous kingdom of murderers and thieves. Putress was the first strike. Many more will come.', 12, 0, 100, 1, 0, 16074, 32693, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32303, 2, 0, 'I''ve waited a long time for this, Thrall. For every time I was thrown into one of your damned arenas... for every time I killed a green-skinned aberration like you... I could think of only one thing.', 12, 0, 100, 1, 0, 16075, 32697, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32303, 3, 0, 'What our world could be without you and your twisted Horde... It ends now, Warchief.', 12, 0, 100, 1, 0, 16076, 32699, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32303, 4, 0, 'ATTACK! FOR STORMWIND! FOR BOLVAR! FOR THE ALLIANCE!', 14, 0, 100, 1, 0, 16077, 32700, 0, 'King Varian Wrynn - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(32315, 0, 0, 'I know what he would do.', 12, 0, 100, 0, 0, 16286, 32731, 0, 'High Overlord Saurfang - Battle for the Undercity'),
(32315, 1, 0, 'He would say to you: Thrall. Lead your people.', 12, 0, 100, 0, 0, 16287, 32732, 0, 'High Overlord Saurfang - Battle for the Undercity'),
(32315, 2, 0, 'Let''s go home, old friend.', 12, 0, 100, 0, 0, 16288, 32733, 0, 'High Overlord Saurfang - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(32401, 0, 0, 'Heroes of the Alliance, your King calls! Gather behind me at the entrance to the sewers!', 14, 0, 100, 1, 0, 16103, 32843, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 1, 0, 'Hidden inside this defiled city is the wretch responsible for murdering our brothers and sisters at the Wrathgate! He must be brought to justice!', 12, 0, 100, 1, 0, 16104, 32979, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 2, 0, 'Soon we will march upon this cursed place and cleanse it of its evil!', 12, 0, 100, 1, 0, 16102, 32844, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 3, 0, 'The hour of redemption is close at hand! Prepare yourselves!', 14, 0, 100, 1, 0, 16101, 32847, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 4, 0, 'The march upon the Undercity begins now! Be empowered by your King''s strength! Follow me, heroes! FOR THE GLORY OF THE ALLIANCE!', 14, 0, 100, 1, 0, 16100, 32849, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 5, 0, 'Onward, brothers and sisters! Destiny awaits!', 14, 0, 100, 1, 0, 16079, 32856, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 6, 0, 'Our descent into the depths of depravity begins! Be on guard! Jaina, lend us your strength!', 12, 0, 100, 1, 0, 16080, 32858, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 7, 0, 'What is this?! Stand your ground! Don''t give them an inch!', 12, 0, 100, 1, 0, 16081, 32859, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 8, 0, 'Soldiers, fall in! Guard the halls!', 14, 0, 100, 1, 0, 16082, 32938, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 9, 0, 'Your aberrations are no match for the Alliance, Putress! We''re coming for you!', 14, 0, 100, 1, 0, 16083, 32937, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 10, 0, 'Horde. By the looks of the struggle, they are here in force - somewhere.', 12, 0, 100, 1, 0, 16084, 32940, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 11, 0, 'Stay alert and on guard. There''s no telling what horrors await us.', 12, 0, 100, 1, 0, 16085, 32941, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 12, 0, 'ONWARD!', 12, 0, 100, 0, 0, 16086, 32942, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 13, 0, 'The main chamber is this way! Let''s go!', 12, 0, 100, 1, 0, 16087, 32945, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 14, 0, 'THERE!', 12, 0, 100, 1, 0, 16088, 32946, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 15, 0, 'There''s nowhere to run, monster!', 14, 0, 100, 1, 0, 16089, 32947, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 16, 0, 'And justice is served!', 14, 0, 100, 1, 0, 16090, 32961, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 17, 0, 'What say you now, Putress?', 12, 0, 100, 1, 0, 16091, 32962, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 18, 0, 'Look around you, brothers and sisters. Open your eyes! Look at what they have done to our kingdom!', 12, 0, 100, 1, 0, 16092, 32963, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 19, 0, 'How much longer will we allow these savages free reign in our world?', 12, 0, 100, 1, 0, 16093, 32964, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 20, 0, 'I have seen the Horde''s world. I have been inside their cities. Inside their minds...', 12, 0, 100, 1, 0, 16094, 32965, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 21, 0, 'I know what evil lies in the hearts of orcs.', 12, 0, 100, 1, 0, 16095, 32966, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 22, 0, 'THRALL! HERE?', 12, 0, 100, 1, 0, 16096, 32968, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 23, 0, 'ONWARD! We end this now!', 12, 0, 100, 1, 0, 16097, 32969, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 24, 0, 'You should all know, the orcs have a battle cry: LOK''TAR OGAR! It means "victory or death." Fitting...', 12, 0, 100, 1, 0, 16098, 32970, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 25, 0, 'To the throne room!', 12, 0, 100, 1, 0, 16099, 32971, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 26, 0, 'I was away for too long. My absence cost us the lives of some of our greatest heroes. Trash like you and this evil witch were allowed to roam free -- unchecked.', 12, 0, 100, 1, 0, 16073, 32691, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 27, 0, 'The time has come to make things right. To disband your treacherous kingdom of murderers and thieves. Putress was the first strike. Many more will come.', 12, 0, 100, 1, 0, 16074, 32693, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 28, 0, 'I''ve waited a long time for this, Thrall. For every time I was thrown into one of your damned arenas... for every time I killed a green-skinned aberration like you... I could think of only one thing.', 12, 0, 100, 1, 0, 16075, 32697, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 29, 0, 'What our world could be without you and your twisted Horde... It ends now, Warchief.', 12, 0, 100, 1, 0, 16076, 32699, 0, 'King Varian Wrynn - Battle for the Undercity'),
(32401, 30, 0, 'ATTACK! FOR STORMWIND! FOR BOLVAR! FOR THE ALLIANCE!', 12, 0, 100, 1, 0, 16077, 32700, 0, 'King Varian Wrynn - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(32402, 0, 0, 'Right away, your majesty!', 12, 0, 100, 1, 0, 16126, 32865, 0, 'Lady Jaina Proudmoore - Battle for the Undercity'),
(32402, 1, 0, 'What''s happened here? There are corpses everywhere... the stench... overwhelming...', 12, 0, 100, 1, 0, 16127, 32939, 0, 'Lady Jaina Proudmoore - Battle for the Undercity'),
(32402, 2, 0, 'Varian, stop! I won''t help you do this!', 12, 0, 100, 1, 0, 16128, 32972, 0, 'Lady Jaina Proudmoore - Battle for the Undercity'),
(32402, 3, 0, 'VARIAN, NO! STOP!', 14, 0, 100, 1, 0, 16122, 32709, 0, 'Lady Jaina Proudmoore - Battle for the Undercity'),
(32402, 4, 0, 'It did not have to be like this...', 12, 0, 100, 1, 0, 16123, 32711, 0, 'Lady Jaina Proudmoore - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(32483, 0, 0, 'Grand Apothecary Putress unleashes the Engorged Blight Worm!', 41, 0, 100, 0, 0, 0, 32928, 0, 'Engorged Blight Worm - Battle for the Undercity');
