(32518, 0, 0, 'WE ARE VICTORIOUS!', 14, 1, 100, 1, 0, 16212, 32643, 0, 'Thrall - Battle for the Undercity'),
(32518, 1, 0, 'The Undercity belongs to the Horde once more! LOK''TAR!', 14, 1, 100, 1, 0, 16214, 32644, 0, 'Thrall - Battle for the Undercity');
