INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(32363, 0, 0, 'Kor''kron, stand down!', 12, 0, 100, 5, 0, 16222, 32286, 0, 'Thrall - Battle for the Undercity'),
(32363, 1, 0, 'Jaina...', 12, 0, 100, 1, 0, 16223, 32287, 0, 'Thrall - Battle for the Undercity'),
(32363, 2, 0, 'Jaina, what happened at the Wrath Gate. It was a betrayal from within...', 12, 0, 100, 1, 0, 16224, 32289, 0, 'Thrall - Battle for the Undercity'),
(32363, 3, 0, 'The Horde has lost the Undercity.', 12, 0, 100, 1, 0, 16225, 32292, 0, 'Thrall - Battle for the Undercity'),
(32363, 4, 0, 'We now prepare to lay siege to the city and bring the perpetrators of this unforgivable crime to justice.', 12, 0, 100, 1, 0, 16226, 32293, 0, 'Thrall - Battle for the Undercity'),
(32363, 5, 0, 'If we are forced into a conflict, the Lich King will destroy our divided forces in Northrend.', 12, 0, 100, 1, 0, 16227, 32294, 0, 'Thrall - Battle for the Undercity'),
(32363, 6, 0, 'We will make this right, Jaina. Tell your king all that you have learned here.', 12, 0, 100, 1, 0, 16228, 32295, 0, 'Thrall - Battle for the Undercity'),
(32363, 7, 0, 'Kor''kron, prepare transport to the Undercity.', 12, 0, 100, 1, 0, 16229, 32300, 0, 'Thrall - Battle for the Undercity');
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(32364, 0, 0, 'Thrall, what has happened? The King is preparing for war...', 12, 0, 100, 1, 0, 16129, 32288, 0, 'Lady Jaina Proudmoore - Battle for the Undercity'),
(32364, 1, 0, 'I will deliver this information to King Wrynn, Thrall, but...', 12, 0, 100, 1, 0, 16130, 32296, 0, 'Lady Jaina Proudmoore - Battle for the Undercity'),
(32364, 2, 0, 'Bolvar was like a brother to him. In the King''s absence, Bolvar kept the Alliance united. He found strength for our people in our darkest hours. He watched over Anduin, raising him as his own. ', 12, 0, 100, 1, 0, 16131, 32297, 0, 'Lady Jaina Proudmoore - Battle for the Undercity'),
(32364, 3, 0, 'I fear that the rage will consume him, Thrall. I remain hopeful that reason will prevail, but we must prepare for the worst... for war.', 12, 0, 100, 1, 0, 16132, 32298, 0, 'Lady Jaina Proudmoore - Battle for the Undercity'),
(32364, 4, 0, 'Farewell, Warchief. I pray that the next time we meet it will be as allies.', 12, 0, 100, 16, 0, 16133, 32299, 0, 'Lady Jaina Proudmoore - Battle for the Undercity');
